// Helper to pick images by index (circular)
function pickRentalImages(startIdx, count) {
  const out = [];
  for (let i = 0; i < count; i++) {
    out.push(RENTAL_IMAGES[(startIdx + i) % RENTAL_IMAGES.length]);
  }
  return out;
}

