// Reverse map: neighborhood slug -> city slug
const neighborhoodToCityMap = {};
for (const [key, nbSlug] of Object.entries(neighborhoodSlugMap)) {
  const [citySlug] = key.split(':');
  neighborhoodToCityMap[nbSlug] = citySlug;
}

// Export to window for other scripts
Object.assign(window, {
  neighborhoodGuides,
  neighborhoodSlugMap,
  neighborhoodToCityMap,
  pickRentalImages,
});
